#!/usr/bin/env python3
"""Focused logic test for the CVE-2016-9588 port.

This reproduces the exact macro definitions from arch/x86/include/asm/vmx.h and
the four changed predicates/decision points from arch/x86/kvm/vmx.c at the
target, then exercises old vs new behavior.  It is a supporting semantic test,
NOT a kernel build.
"""
import os
import subprocess
import sys
import tempfile

C_SOURCE = r'''
#include <stdio.h>
#include <stdbool.h>
typedef unsigned int u32;

#define INTR_INFO_VECTOR_MASK           0xff
#define INTR_INFO_INTR_TYPE_MASK        0x700
#define INTR_INFO_VALID_MASK            0x80000000
#define INTR_TYPE_EXT_INTR              (0 << 8)
#define INTR_TYPE_NMI_INTR              (2 << 8)
#define INTR_TYPE_HARD_EXCEPTION        (3 << 8)
#define INTR_TYPE_SOFT_INTR             (4 << 8)
#define INTR_TYPE_SOFT_EXCEPTION        (6 << 8)

/* pre-fix helper */
static inline bool is_exception(u32 intr_info)
{
	return (intr_info & (INTR_INFO_INTR_TYPE_MASK | INTR_INFO_VALID_MASK))
		== (INTR_TYPE_HARD_EXCEPTION | INTR_INFO_VALID_MASK);
}
/* post-fix helper */
static inline bool is_nmi(u32 intr_info)
{
	return (intr_info & (INTR_INFO_INTR_TYPE_MASK | INTR_INFO_VALID_MASK))
		== (INTR_TYPE_NMI_INTR | INTR_INFO_VALID_MASK);
}

/* nested_vmx_exit_handled(), EXIT_REASON_EXCEPTION_NMI: 1 == L1 handles */
static int nested_old(u32 intr_info, u32 exception_bitmap)
{
	if (!is_exception(intr_info))
		return 0;
	return (exception_bitmap & (1u << (intr_info & INTR_INFO_VECTOR_MASK))) ? 1 : 0;
}
static int nested_new(u32 intr_info, u32 exception_bitmap)
{
	if (is_nmi(intr_info))
		return 0;
	return (exception_bitmap & (1u << (intr_info & INTR_INFO_VECTOR_MASK))) ? 1 : 0;
}

/* handle_exception() early "already handled NMI" return */
static int handle_old(u32 intr_info)
{
	return ((intr_info & INTR_INFO_INTR_TYPE_MASK) == INTR_TYPE_NMI_INTR) ? 1 : 0;
}
static int handle_new(u32 intr_info)
{
	return is_nmi(intr_info) ? 1 : 0;
}

/* vmx_complete_atomic_exit() NMI injection guard */
static int atomic_old(u32 i) { return ((i & INTR_INFO_INTR_TYPE_MASK) == INTR_TYPE_NMI_INTR) && (i & INTR_INFO_VALID_MASK); }
static int atomic_new(u32 i) { return is_nmi(i); }

static int failures = 0;
#define CHECK(name, cond) do { \
	if (cond) { printf("PASS %s\n", name); } \
	else { printf("FAIL %s\n", name); failures++; } \
} while (0)

int main(void)
{
	u32 bp  = INTR_TYPE_SOFT_EXCEPTION | INTR_INFO_VALID_MASK | 3;   /* #BP (INT3)  */
	u32 of  = INTR_TYPE_SOFT_EXCEPTION | INTR_INFO_VALID_MASK | 4;   /* #OF (INTO)  */
	u32 pf  = INTR_TYPE_HARD_EXCEPTION | INTR_INFO_VALID_MASK | 14;  /* #PF         */
	u32 nmi = INTR_TYPE_NMI_INTR | INTR_INFO_VALID_MASK | 2;         /* NMI valid   */
	u32 bad = INTR_TYPE_NMI_INTR | 2;                                /* NMI invalid */
	u32 ext = INTR_TYPE_EXT_INTR | INTR_INFO_VALID_MASK;             /* ext irq     */
	u32 bmp = (1u << 3) | (1u << 4) | (1u << 14);

	/* I1 truth table */
	CHECK("is_nmi(NMI valid)=1",  is_nmi(nmi) == 1);
	CHECK("is_nmi(NMI invalid)=0", is_nmi(bad) == 0);
	CHECK("is_nmi(hard exc)=0",   is_nmi(pf) == 0);
	CHECK("is_nmi(soft exc)=0",   is_nmi(bp) == 0);
	CHECK("is_nmi(ext intr)=0",   is_nmi(ext) == 0);

	/* I2: L1-requested software exception intercept is honored by new code */
	CHECK("nested old #BP -> L0 (vulnerable)", nested_old(bp, bmp) == 0);
	CHECK("nested new #BP -> L1 (fixed)",      nested_new(bp, bmp) == 1);
	CHECK("nested old #OF -> L0 (vulnerable)", nested_old(of, bmp) == 0);
	CHECK("nested new #OF -> L1 (fixed)",      nested_new(of, bmp) == 1);
	/* genuine NMI must still be handled by L0 in both */
	CHECK("nested old NMI -> L0", nested_old(nmi, bmp) == 0);
	CHECK("nested new NMI -> L0", nested_new(nmi, bmp) == 0);
	/* hardware exception still consults exception_bitmap in both */
	CHECK("nested old #PF -> L1", nested_old(pf, bmp) == 1);
	CHECK("nested new #PF -> L1", nested_new(pf, bmp) == 1);
	/* without an L1 intercept bit the exception is not reflected */
	CHECK("nested new #BP no-intercept -> L0", nested_new(bp, 0) == 0);

	/* I3: type-only test misclassifies invalid NMI; new code does not */
	CHECK("handle old NMI-invalid misclassified", handle_old(bad) == 1);
	CHECK("handle new NMI-invalid not NMI",       handle_new(bad) == 0);
	CHECK("handle old NMI-valid", handle_old(nmi) == 1);
	CHECK("handle new NMI-valid", handle_new(nmi) == 1);

	/* I4: atomic-exit guard is boolean-equivalent before/after */
	CHECK("atomic old==new NMI-valid",   atomic_old(nmi) == atomic_new(nmi));
	CHECK("atomic old==new NMI-invalid", atomic_old(bad) == atomic_new(bad));
	CHECK("atomic old==new soft-exc",    atomic_old(bp)  == atomic_new(bp));

	if (failures == 0)
		printf("ALL LOGIC TESTS PASSED\n");
	else
		printf("%d LOGIC TEST(S) FAILED\n", failures);
	return failures == 0 ? 0 : 1;
}
'''

def main() -> int:
    with tempfile.TemporaryDirectory(prefix="cve-2016-9588-logic-") as td:
        c_path = os.path.join(td, "logic_test.c")
        bin_path = os.path.join(td, "logic_test")
        with open(c_path, "w", encoding="utf-8") as fh:
            fh.write(C_SOURCE)
        compile_proc = subprocess.run(
            ["gcc-10", "-O0", "-Wall", "-o", bin_path, c_path],
            capture_output=True, text=True)
        sys.stdout.write(compile_proc.stdout)
        sys.stderr.write(compile_proc.stderr)
        if compile_proc.returncode != 0:
            print("COMPILE FAILED")
            return 2
        run_proc = subprocess.run([bin_path], capture_output=True, text=True)
        sys.stdout.write(run_proc.stdout)
        sys.stderr.write(run_proc.stderr)
        return run_proc.returncode

if __name__ == "__main__":
    raise SystemExit(main())

