int main(void)
{
	u32 bp  = INTR_TYPE_SOFT_EXCEPTION | INTR_INFO_VALID_MASK | 3;   /* #BP (INT3)  */
	u32 of  = INTR_TYPE_SOFT_EXCEPTION | INTR_INFO_VALID_MASK | 4;   /* #OF (INTO)  */
	u32 pf  = INTR_TYPE_HARD_EXCEPTION | INTR_INFO_VALID_MASK | 14;  /* #PF         */
	u32 nmi = INTR_TYPE_NMI_INTR | INTR_INFO_VALID_MASK | 2;         /* NMI valid   */
	u32 bad = INTR_TYPE_NMI_INTR | 2;                                /* NMI invalid */
	u32 ext = INTR_TYPE_EXT_INTR | INTR_INFO_VALID_MASK;             /* ext irq     */
	u32 bmp = (1u << 3) | (1u << 4) | (1u << 14);

	/* I1 truth table */
	CHECK("is_nmi(NMI valid)=1",  is_nmi(nmi) == 1);
	CHECK("is_nmi(NMI invalid)=0", is_nmi(bad) == 0);
	CHECK("is_nmi(hard exc)=0",   is_nmi(pf) == 0);
	CHECK("is_nmi(soft exc)=0",   is_nmi(bp) == 0);
	CHECK("is_nmi(ext intr)=0",   is_nmi(ext) == 0);

	/* I2: L1-requested software exception intercept is honored by new code */
	CHECK("nested old #BP -> L0 (vulnerable)", nested_old(bp, bmp) == 0);
	CHECK("nested new #BP -> L1 (fixed)",      nested_new(bp, bmp) == 1);
	CHECK("nested old #OF -> L0 (vulnerable)", nested_old(of, bmp) == 0);
	CHECK("nested new #OF -> L1 (fixed)",      nested_new(of, bmp) == 1);
	/* genuine NMI must still be handled by L0 in both */
	CHECK("nested old NMI -> L0", nested_old(nmi, bmp) == 0);
	CHECK("nested new NMI -> L0", nested_new(nmi, bmp) == 0);
	/* hardware exception still consults exception_bitmap in both */
	CHECK("nested old #PF -> L1", nested_old(pf, bmp) == 1);
	CHECK("nested new #PF -> L1", nested_new(pf, bmp) == 1);
	/* without an L1 intercept bit the exception is not reflected */
	CHECK("nested new #BP no-intercept -> L0", nested_new(bp, 0) == 0);

	/* I3: type-only test misclassifies invalid NMI; new code does not */
	CHECK("handle old NMI-invalid misclassified", handle_old(bad) == 1);
	CHECK("handle new NMI-invalid not NMI",       handle_new(bad) == 0);
	CHECK("handle old NMI-valid", handle_old(nmi) == 1);
	CHECK("handle new NMI-valid", handle_new(nmi) == 1);

	/* I4: atomic-exit guard is boolean-equivalent before/after */
	CHECK("atomic old==new NMI-valid",   atomic_old(nmi) == atomic_new(nmi));
	CHECK("atomic old==new NMI-invalid", atomic_old(bad) == atomic_new(bad));
	CHECK("atomic old==new soft-exc",    atomic_old(bp)  == atomic_new(bp));

	if (failures == 0)
		printf("ALL LOGIC TESTS PASSED\n");
	else
		printf("%d LOGIC TEST(S) FAILED\n", failures);
	return failures == 0 ? 0 : 1;
}
